function openRewardForm(id){const s=state(),g=list(s).find(x=>String(x.id)===String(id));if(!g)return;overlay(`${sheetHead('',`Belønning til ${g.owner}`,'Målet endres ikke. Poeng trekkes først ved innløsning.')}<form id="partnerRewardForm" data-goal-id="${esc(g.id)}"><div class="goalFormCard"><label class="goalFormRow"><span>Belønning</span><select name="preset">${rewardOptions()}</select></label><label class="goalFormRow"><span>Eget forslag</span><input name="custom" maxlength="100" placeholder="Skriv en belønning"></label><div class="goalFormRow"><span>Poengpris</span>${pointStepper('cost',60,'poeng')}</div><label class="goalCheck"><span>Hold hemmelig 🔒</span><input name="secret" type="checkbox"></label></div><button class="goalPrimary goalFormSubmit">Legg til belønning</button><button type="button" class="goalTextAction" data-goal-close>Avbryt</button></form>`)}
function openOfferForm(){const s=state();overlay(`${sheetHead('',`Tilby noe til ${partner(s)}`,'Partneren velger selv om og når poengene brukes.')}<form id="rewardOfferForm"><div class="goalFormCard"><label class="goalFormRow"><span>Belønning</span><input name="title" maxlength="100" placeholder="Hva vil du tilby?"></label><div class="goalFormRow"><span>Poengpris</span>${pointStepper('cost',60,'poeng')}</div><label class="goalCheck"><span>Hemmelig fristelse 🔒</span><input name="secret" type="checkbox"></label></div><button class="goalPrimary goalFormSubmit">Tilby belønningen</button><button type="button" class="goalTextAction" data-goal-close>Avbryt</button></form>`)}
function openLibraryReward(title,category){const dependent=core().requiresPartner(title,category),cost=core().rewardCost(title);overlay(`${sheetHead('Forslag',title,dependent?'Dette må avtales med partneren før poeng kan brukes.':'Du kan bruke dette i et mål eller be partneren tilby det.')}<div class="goalDetailCard"><div class="goalDetailLine"><b>Poengpris</b><span>${cost} poeng</span></div><div class="goalDetailLine"><b>Status</b><span>${dependent?'Krever partner':'Forslag'}</span></div></div><div class="goalActions">${dependent?`<button class="goalPrimary" data-library-request="${esc(title)}" data-library-cost="${cost}" data-library-category="${esc(category)}">Ønsk deg denne</button>`:''}<button class="goalSecondary" data-library-use-goal="${esc(title)}">Bruk i et mål</button><button class="goalTextAction" data-goal-close>Tilbake</button></div>`)}
function openHistory(){const s=state(),history=list(s),order=['Venter på svar','Aktiv','Mål nådd','Klar til bruk','Brukt / gjennomført','Ikke fullført','Avslått','Avsluttet'],groups=order.map(label=>[label,history.filter(g=>statusText(g).includes(label))]).filter(([,a])=>a.length);overlay(`${sheetHead('Mål og belønning','Historikk','Måloppnåelse beholdes selv om poengene brukes på noe annet.')}${groups.length?groups.map(([label,items])=>`<div class="goalStatusGroup"><h3>${esc(label)}</h3><div class="goalList">${items.map(x=>goalCard(s,x)).join('')}</div></div>`).join(''):'<p class="goalEmpty">Ingen historikk ennå.</p>'}`)}
const ask=opts=>window.FlytModal?.confirm?window.FlytModal.confirm(opts):Promise.resolve(true);
async function confirmAndRedeem(item){const s=state();if(item.direct){const result=core().redeemGoalReward(s,item.goalId,s.user);if(result.ok){save(result.state,'Avtalen er klar');$('#goalSheetLayer')?.remove();render()}return}const shared=!!item.shared,balance=shared?Object.values(s.points||{}).reduce((a,b)=>a+Math.max(0,Number(b)||0),0):Math.max(0,Number(s.points?.[s.user])||0),cost=Math.max(1,Number(item.cost)||1);if(balance<cost){bridge()?.toast?.(`Du mangler ${cost-balance} poeng`);return}const ok=await ask({ey:'Bruk poeng',title:`Bruke ${cost} poeng på ${item.title}?`,text:`Du har ${balance} poeng tilgjengelig. Poengene trekkes først når du bekrefter.`,ok:`Bruk ${cost} poeng`,cancel:'Avbryt'});if(!ok)return;const result=item.goalId?core().redeemGoalReward(s,item.goalId,s.user):core().redeemCatalogReward(s,item,s.user);if(!result.ok){bridge()?.toast?.('Ikke nok tilgjengelige poeng');return}save(result.state,'Belønningen er klar til bruk');$('#goalSheetLayer')?.remove();render()}
function legacyRewardStatus(balance,r){if(!r?.requiresPoints)return{label:'Åpen',ready:true,missing:0,pct:100};const cost=Math.max(1,Number(r.cost)||1),missing=Math.max(0,cost-Number(balance||0));return{label:missing?`Mangler ${missing}`:'Klar',ready:missing===0,missing,pct:Math.min(100,Math.round(Number(balance||0)/cost*100))}}
async function activateLegacy(id){const s=state(),r=(s?.rewards||[]).find(x=>String(x.id)===String(id));if(!s||!r)return;const st=legacyRewardStatus(s.points?.[s.user],r);if(!st.ready)return;const cost=r.requiresPoints?Math.max(1,Number(r.cost)||1):0,points={...(s.points||{})};if(cost)points[s.user]=Math.max(0,Number(points[s.user]||0)-cost);save({...s,points,rewardRedemptions:[{id:`red_${Date.now()}`,rewardId:r.id,title:r.title,offeredBy:r.by,claimedBy:s.user,cost,claimedAt:new Date().toISOString(),claimedAtMs:Date.now(),done:false},...(s.rewardRedemptions||[])]})}
document.addEventListener('change',e=>{const f=e.target.closest('#goalEditor');if(f){updateFormVisibility()}const rf=e.target.closest('#partnerRewardForm');if(rf&&e.target.name==='preset'&&e.target.value&&e.target.value!=='__custom__')rf.elements.cost.value=core().rewardCost(e.target.value)},true);
document.addEventListener('input',e=>{if(e.target.closest('#goalEditor'))updateFormVisibility()},true);
document.addEventListener('scroll',e=>{const wheel=e.target.closest?.('.pointWheel');if(wheel)syncPointWheel(wheel)},true);
document.addEventListener('input',e=>{const picker=e.target.closest('#pointPickerLayer');if(picker&&e.target.matches('[data-point-manual-input]')){const value=Number(e.target.value);if(Number.isInteger(value)&&value>0)picker.dataset.value=String(value)}},true);
document.addEventListener('change',e=>{const task=e.target.closest('#goalEditor [data-challenge-task-select]');if(task&&task.value==='__custom__'){setChallengeCustom(task.closest('#goalEditor'));return}const picker=e.target.closest('#deadlinePickerLayer');if(!picker)return;if(e.target.matches('[data-deadline-date-input]')&&e.target.value)openDeadlinePicker($('#goalEditor'),{date:e.target.value,time:picker.dataset.time});if(e.target.matches('[data-deadline-time-input]')&&e.target.value)openDeadlinePicker($('#goalEditor'),{date:picker.dataset.date,time:e.target.value})},true);
document.addEventListener('submit',e=>{
  const f=e.target.closest('#goalEditor');if(f){e.preventDefault();const input=readForm(f);if(!input)return;const s=state(),id=f.dataset.goalId;if(f.dataset.proposal==='1')save(core().proposeChange(s,id,input,s.user),'Endringsforslaget er sendt');else if(id)save(core().editPendingGoal(s,id,input,s.user),'Forslaget er oppdatert');else save(core().createGoal(s,input),'Målet er lagt til');$('#goalSheetLayer')?.remove();render();return}
  const rf=e.target.closest('#partnerRewardForm');if(rf){e.preventDefault();const s=state(),title=rf.elements.preset.value==='__custom__'?rf.elements.custom.value.trim():(rf.elements.preset.value||rf.elements.custom.value.trim());if(!title){bridge()?.toast?.('Velg eller skriv en belønning');return}save(core().addPartnerReward(s,rf.dataset.goalId,{title,cost:Math.max(1,Number(rf.elements.cost.value)||60),secret:!!rf.elements.secret.checked},s.user),'Belønningen er lagt til');$('#goalSheetLayer')?.remove();render();return}
  const of=e.target.closest('#rewardOfferForm');if(of){e.preventDefault();const s=state(),title=of.elements.title.value.trim();if(!title){bridge()?.toast?.('Skriv inn belønningen');return}save(core().addRewardOffer(s,{title,cost:Math.max(1,Number(of.elements.cost.value)||60),secret:!!of.elements.secret.checked},s.user),'Belønningen er tilbudt');$('#goalSheetLayer')?.remove();render()}
},true);
document.addEventListener('click',async e=>{
  const nav=e.target.closest('#nav button[data-view="rewards"]');if(nav){e.preventDefault();e.stopImmediatePropagation();const s=state();if(s&&s.view!=='rewards')save({...s,view:'rewards'});render({resetScroll:true});return}
  const pointOpen=e.target.closest('[data-point-open]');if(pointOpen){openPointPicker(pointOpen.closest('form'),pointOpen.dataset.pointInput,pointOpen.dataset.pointUnit);return}
  const pointPicker=e.target.closest('#pointPickerLayer');if(pointPicker){const option=e.target.closest('[data-point-value]');if(option){const form=$('#goalEditor'),input=form.elements[pointPicker.dataset.input],previous=input.value;input.value=option.dataset.pointValue;openPointPicker(form,pointPicker.dataset.input,pointPicker.dataset.unit);input.value=previous;return}if(e.target.closest('[data-point-manual]')){const input=pointPicker.querySelector('[data-point-manual-input]');input.hidden=false;input.focus();return}if(e.target.closest('[data-point-finish]')){const value=Number(pointPicker.dataset.value),form=$('#goalEditor');if(!Number.isInteger(value)||value<1){bridge()?.toast?.('Oppgi et helt, positivt antall poeng');return}const input=form.elements[pointPicker.dataset.input];input.value=String(value);input.closest('.pointSelect').querySelector('[data-point-summary]').textContent=`${value} ${pointPicker.dataset.unit}`;pointPicker.remove();return}if(e.target.closest('[data-point-cancel]')){pointPicker.remove();return}}
  const deadlineOpen=e.target.closest('[data-deadline-open]');if(deadlineOpen){openDeadlinePicker(deadlineOpen.closest('#goalEditor'));return}
  const picker=e.target.closest('#deadlinePickerLayer');if(picker){const date=e.target.closest('[data-deadline-date]'),time=e.target.closest('[data-deadline-time]');if(date){openDeadlinePicker($('#goalEditor'),{date:date.dataset.deadlineDate,time:picker.dataset.time});return}if(time){openDeadlinePicker($('#goalEditor'),{date:picker.dataset.date,time:time.dataset.deadlineTime});return}if(e.target.closest('[data-deadline-custom-date]')){const input=picker.querySelector('[data-deadline-date-input]');input.hidden=false;input.showPicker?.();return}if(e.target.closest('[data-deadline-custom-time]')){const input=picker.querySelector('[data-deadline-time-input]');input.hidden=false;input.showPicker?.();return}if(e.target.closest('[data-deadline-finish]')){const f=$('#goalEditor'),dateValue=picker.dataset.date,timeValue=picker.dataset.time;f.elements.deadline.value=timeValue==='none'?dateValue:new Date(`${dateValue}T${timeValue}:00`).toISOString();f.querySelector('[data-deadline-summary]').textContent=deadlineLabel(f.elements.deadline.value);picker.remove();return}if(e.target.closest('[data-deadline-cancel]')){picker.remove();return}}
  if(e.target.closest('[data-goal-close]')){$('#goalSheetLayer')?.remove();return}
  const tab=e.target.closest('[data-goal-tab]');if(tab){activeTab=tab.dataset.goalTab;render({resetScroll:true});return}
  const category=e.target.closest('[data-reward-category]');if(category){rewardCategory=category.dataset.rewardCategory;render();return}
  const advanced=e.target.closest('[data-goal-advanced-toggle]');if(advanced){const f=advanced.closest('#goalEditor');f.dataset.advanced=f.dataset.advanced==='1'?'0':'1';updateFormVisibility();return}
  const adjust=e.target.closest('[data-point-adjust]');if(adjust){const f=adjust.closest('form'),input=f?.elements?.[adjust.dataset.pointInput];if(input){const step=Math.max(1,Number(input.step)||5),direction=Number(adjust.dataset.pointAdjust)||0,min=Math.max(1,Number(input.min)||1),max=Math.max(min,Number(input.max)||9999);input.value=String(Math.max(min,Math.min(max,(Number(input.value)||min)+(direction*step))));if(f.id==='goalEditor')updateFormVisibility()}return}
  const choice=e.target.closest('[data-goal-choice]');if(choice){openGoalChoice();return}
  const create=e.target.closest('[data-goal-create]');if(create){openForm(create.dataset.goalCreate);return}
  const open=e.target.closest('[data-goal-open]');if(open){openDetail(open.dataset.goalOpen);return}
  if(e.target.closest('[data-goal-history]')){openHistory();return}if(e.target.closest('[data-offer-create]')){openOfferForm();return}
  const val=name=>e.target.closest(`[${name}]`)?.getAttribute(name);let id=val('data-goal-edit');if(id){const g=list(state()).find(x=>String(x.id)===String(id));openForm(g.kind,{goal:g});return}
  id=val('data-goal-accept');if(id){save(core().acceptGoal(state(),id,state().user),'Avtalen er godkjent og låst. Ingen poeng er reservert.');$('#goalSheetLayer')?.remove();render();return}
  id=val('data-goal-decline');if(id){if(await ask({ey:'Mål og belønning',title:'Avslå forslaget?',text:'Forslaget flyttes til historikken.',ok:'Avslå'})){save(core().declineGoal(state(),id,state().user),'Forslaget er avslått');$('#goalSheetLayer')?.remove();render()}return}
  id=val('data-goal-propose');if(id){const g=list(state()).find(x=>String(x.id)===String(id));openForm(g.kind,{goal:g,proposal:g.status==='active'});return}
  id=val('data-goal-cancel');if(id){if(await ask({ey:'Utfordring',title:'Foreslå å avslutte?',text:'Utfordringen avsluttes bare hvis partneren godtar.',ok:'Send forslag'})){save(core().proposeChange(state(),id,{cancel:true},state().user),'Forslaget er sendt');$('#goalSheetLayer')?.remove();render()}return}
  id=val('data-change-accept');if(id){save(core().respondToChange(state(),id,state().user,true),'Endringen er godkjent');$('#goalSheetLayer')?.remove();render();return}
  id=val('data-change-decline');if(id){save(core().respondToChange(state(),id,state().user,false),'Endringen er avslått');$('#goalSheetLayer')?.remove();render();return}
  id=val('data-goal-manual');if(id){save(core().markManualDone(state(),id,state().user),'Målet er markert som nådd. Poengene er ikke trukket.');$('#goalSheetLayer')?.remove();render();return}
  id=val('data-goal-add-reward');if(id){openRewardForm(id);return}
  id=val('data-reward-approve');if(id){save(core().approveReward(state(),id,state().user,true),'Belønningen er godkjent');$('#goalSheetLayer')?.remove();render();return}
  id=val('data-reward-decline');if(id){save(core().approveReward(state(),id,state().user,false),'Ønsket er avslått');$('#goalSheetLayer')?.remove();render();return}
  id=val('data-reward-redeem');if(id){const g=list(state()).find(x=>String(x.id)===String(id));await confirmAndRedeem({goalId:id,title:g.reward.title,cost:g.reward.cost,direct:!!g.reward.direct,shared:g.kind==='shared'});return}
  id=val('data-reward-used');if(id){save(core().markRewardUsed(state(),id,state().user),'Belønningen er markert som brukt');$('#goalSheetLayer')?.remove();render();return}
  const catalog=e.target.closest('[data-catalog-redeem]');if(catalog){await confirmAndRedeem({title:catalog.dataset.catalogRedeem,cost:Number(catalog.dataset.catalogCost),offerId:catalog.dataset.offerId||null});return}
  const library=e.target.closest('[data-library-reward]');if(library){openLibraryReward(library.dataset.libraryReward,library.dataset.libraryCategory);return}
  const wish=e.target.closest('[data-library-request]');if(wish){save(core().requestRewardOffer(state(),{title:wish.dataset.libraryRequest,cost:Number(wish.dataset.libraryCost),category:wish.dataset.libraryCategory},state().user),'Ønsket er sendt til partneren');$('#goalSheetLayer')?.remove();render();return}
  const useGoal=e.target.closest('[data-library-use-goal]');if(useGoal){$('#goalSheetLayer')?.remove();openGoalChoice();return}
  id=val('data-offer-approve');if(id){save(core().respondToRewardOffer(state(),id,state().user,true),'Belønningen er nå tilgjengelig for partneren');render();return}
  id=val('data-offer-decline');if(id){save(core().respondToRewardOffer(state(),id,state().user,false),'Ønsket er avslått');render();return}
  id=val('data-purchase-used');if(id){save(core().markPurchaseUsed(state(),id,state().user),'Belønningen er markert som brukt');$('#goalSheetLayer')?.remove();render()}
},true);
